<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
$module = in_array($_GET['module'] ?? '', ['presentation','impact','contacts','standards'], true) ? (string) $_GET['module'] : 'presentation';
$permission = ['presentation'=>'presentation','impact'=>'impact','contacts'=>'contacts','standards'=>'editor'][$module];
$user = require_permission($permission, 'view');
$db = admin_db();
$error = '';

if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST') {
    try {
        verify_csrf();$releasedPaths=[];$failedUploads=[];$changedScope='';
        $action = (string) ($_POST['action'] ?? '');
        $recordId = (int) ($_POST['id'] ?? 0);
        require_permission($permission, $module==='standards'?'edit':(str_starts_with($action, 'delete-') ? 'delete' : ($recordId ? 'edit' : 'create')));
        if ($action === 'save-entry' && $module !== 'contacts') {
            $id = (int) ($_POST['id'] ?? 0);
            $titleEs = trim((string) ($_POST['title_es'] ?? ''));
            if ($titleEs === '') throw new RuntimeException('El título en español es obligatorio.');
            if($id){$previousStatement=$db->prepare('SELECT logo_path,cover_path FROM cms_collections WHERE id=? AND module_key=?');$previousStatement->execute([$id,$module]);$previous=$previousStatement->fetch();if($previous)$releasedPaths=[(string)$previous['logo_path'],(string)$previous['cover_path']];}
            $creation='';$logo = save_upload($db, $_FILES['logo'] ?? [], (int) $user['id'], $creation) ?: trim((string) ($_POST['logo_path'] ?? ''));if($creation!=='')$failedUploads[]=['path'=>$logo,'creation'=>$creation];
            $creation='';$cover = save_upload($db, $_FILES['cover'] ?? [], (int) $user['id'], $creation) ?: trim((string) ($_POST['cover_path'] ?? ''));if($creation!=='')$failedUploads[]=['path'=>$cover,'creation'=>$creation];$db->beginTransaction();
            $entryType=$module==='standards'?'standard':(($_POST['entry_type'] ?? '') === 'presence' ? 'presence' : 'event');
            $values = [$module,$entryType,$titleEs,trim((string)($_POST['title_en'] ?? '')),trim((string)($_POST['description_es'] ?? '')),trim((string)($_POST['description_en'] ?? '')),$module==='standards'?null:(($_POST['event_date'] ?? '') ?: null),$module==='standards'?'':trim((string)($_POST['location_es'] ?? '')),$module==='standards'?'':trim((string)($_POST['location_en'] ?? '')),$logo,$module==='standards'?'':$cover,isset($_POST['is_active']),max(0,(int)($_POST['sort_order'] ?? 0))];
            if ($id) {
                $values[] = $id; $values[] = $module;
                $db->prepare('UPDATE cms_collections SET module_key=?,entry_type=?,title_es=?,title_en=?,description_es=?,description_en=?,event_date=?,location_es=?,location_en=?,logo_path=?,cover_path=?,is_active=?,sort_order=? WHERE id=? AND module_key=?')->execute($values);
            } else {
                $db->prepare('INSERT INTO cms_collections(module_key,entry_type,title_es,title_en,description_es,description_en,event_date,location_es,location_en,logo_path,cover_path,is_active,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($values);
                $id = (int) $db->lastInsertId();
            }
            if (!empty($_FILES['gallery']['name'][0])) {
                $insert = $db->prepare('INSERT INTO cms_collection_media(collection_id,media_path,caption_es,caption_en,sort_order) VALUES(?,?,?,?,?)');
                foreach ($_FILES['gallery']['name'] as $index => $name) {
                    $file = ['name'=>$name,'type'=>$_FILES['gallery']['type'][$index],'tmp_name'=>$_FILES['gallery']['tmp_name'][$index],'error'=>$_FILES['gallery']['error'][$index],'size'=>$_FILES['gallery']['size'][$index]];
                    $creation='';$path = save_upload($db, $file, (int) $user['id'], $creation);if($creation!=='')$failedUploads[]=['path'=>$path,'creation'=>$creation];
                    if ($path) $insert->execute([$id,$path,$titleEs,trim((string)($_POST['title_en'] ?? '')),$index + 100]);
                }
            }
            audit($db,(int)$user['id'],'save',$module,$id);$changedScope=$module;flash('success',$module==='standards'?'Certificado guardado y actualizado en la web.':'Contenido guardado y actualizado en la web.');
        } elseif ($action === 'delete-entry' && $module !== 'contacts') {
            $id=(int)($_POST['id']??0);$previousStatement=$db->prepare("SELECT logo_path path FROM cms_collections WHERE id=? AND module_key=? UNION ALL SELECT cover_path FROM cms_collections WHERE id=? AND module_key=? UNION ALL SELECT m.media_path FROM cms_collection_media m JOIN cms_collections c ON c.id=m.collection_id WHERE c.id=? AND c.module_key=?");$previousStatement->execute([$id,$module,$id,$module,$id,$module]);$releasedPaths=$previousStatement->fetchAll(PDO::FETCH_COLUMN);$db->prepare('DELETE FROM cms_collections WHERE id=? AND module_key=?')->execute([$id,$module]);audit($db,(int)$user['id'],'delete',$module,$id);$changedScope=$module;flash('success',$module==='standards'?'Certificado eliminado de la web.':'Contenido eliminado.');
        } elseif ($action === 'delete-media' && $module !== 'contacts') {
            $id=(int)($_POST['id']??0);$previousStatement=$db->prepare('SELECT m.media_path FROM cms_collection_media m JOIN cms_collections c ON c.id=m.collection_id WHERE m.id=? AND c.module_key=?');$previousStatement->execute([$id,$module]);$releasedPaths=[(string)($previousStatement->fetchColumn()?:'')];$db->prepare('DELETE m FROM cms_collection_media m JOIN cms_collections c ON c.id=m.collection_id WHERE m.id=? AND c.module_key=?')->execute([$id,$module]);$changedScope=$module;flash('success','Imagen retirada del álbum.');
        } elseif ($action === 'save-contact' && $module === 'contacts') {
            $id=(int)($_POST['id']??0);$type=in_array($_POST['channel_type']??'', ['email','phone','whatsapp','address','facebook','instagram','youtube','linkedin','tiktok','other'],true)?$_POST['channel_type']:'other';
            $values=[$type,trim((string)($_POST['label_es']??'')),trim((string)($_POST['label_en']??'')),trim((string)($_POST['value_text']??'')),trim((string)($_POST['link_url']??'')),isset($_POST['is_active']),max(0,(int)($_POST['sort_order']??0))];
            if($values[1]===''||$values[3]==='')throw new RuntimeException('Completa el nombre y el valor del canal.');
            if($id){$values[]=$id;$db->prepare('UPDATE contact_channels SET channel_type=?,label_es=?,label_en=?,value_text=?,link_url=?,is_active=?,sort_order=? WHERE id=?')->execute($values);}else{$db->prepare('INSERT INTO contact_channels(channel_type,label_es,label_en,value_text,link_url,is_active,sort_order) VALUES(?,?,?,?,?,?,?)')->execute($values);$id=(int)$db->lastInsertId();}
            audit($db,(int)$user['id'],'save','contact-channel',$id);mark_public_content_changed('contacts');flash('success','Canal de contacto guardado y actualizado en la web.');
        } elseif ($action === 'delete-contact' && $module === 'contacts') {
            $id=(int)($_POST['id']??0);$db->prepare('DELETE FROM contact_channels WHERE id=?')->execute([$id]);audit($db,(int)$user['id'],'delete','contact-channel',$id);mark_public_content_changed('contacts');flash('success','Canal eliminado y actualizado en la web.');
        }
        if($db->inTransaction())$db->commit();$failedUploads=[];if($releasedPaths){$currentId=$recordId?:($id??0);$currentPaths=$action==='save-entry'?current_collection_media_paths($db,(int)$currentId):[];$cleanup=release_replaced_media($db,$releasedPaths,$currentPaths,(int)$user['id'],$module,$currentId);if($cleanup['errors'])audit($db,(int)$user['id'],'cleanup-failed','media',$recordId,$cleanup);}if($changedScope!=='')mark_public_content_changed($changedScope);header('Location: /admin/sections.php?module='.rawurlencode($module)); exit;
    } catch (Throwable $exception) {if($db->inTransaction())$db->rollBack();$cleanup=cleanup_failed_uploads($db,$failedUploads??[]);$error = $exception->getMessage().($cleanup['errors']?' No se pudieron limpiar algunas cargas temporales.':''); }
}
$flash=pull_flash();$editingId=(int)($_GET['edit']??0);$editorOpen=$editingId>0||isset($_GET['create'])||$error!=='';$labels=['presentation'=>'Participación','impact'=>'Impacto','contacts'=>'Contactos','standards'=>'Certificados'];
$entries=[];$editing=null;$gallery=[];
if($module!=='contacts'){$s=$db->prepare('SELECT c.*,(SELECT COUNT(*) FROM cms_collection_media m WHERE m.collection_id=c.id) AS media_count FROM cms_collections c WHERE c.module_key=? ORDER BY c.entry_type,c.sort_order,c.event_date DESC,c.id DESC');$s->execute([$module]);$entries=$s->fetchAll();if($editingId){$s=$db->prepare('SELECT * FROM cms_collections WHERE id=? AND module_key=?');$s->execute([$editingId,$module]);$editing=$s->fetch();if($editing){$s=$db->prepare('SELECT * FROM cms_collection_media WHERE collection_id=? ORDER BY sort_order,id');$s->execute([$editingId]);$gallery=$s->fetchAll();}}}
else{$entries=$db->query('SELECT * FROM contact_channels ORDER BY sort_order,id')->fetchAll();if($editingId){$s=$db->prepare('SELECT * FROM contact_channels WHERE id=?');$s->execute([$editingId]);$editing=$s->fetch();}}
$publishedCount=count(array_filter($entries,static fn(array $item):bool=>(bool)$item['is_active']));$publicPath=$module==='presentation'?'/participacion/':($module==='impact'?'/impacto/':($module==='standards'?'/nosotros/':'/contacto/'));
function nav_link(string $href,string $label,string $active=''):string{return '<a'.($active?' class="active"':'').' href="'.e($href).'">'.e($label).'</a>';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($labels[$module])?> | Royal Beans Perú</title><link rel="stylesheet" href="/admin/admin.css"></head><body class="admin-body"><aside class="admin-sidebar"><a class="admin-brand" href="/admin/"><img src="/images/logo.webp" alt=""><span><strong>ROYAL BEANS</strong><small>ADMINISTRACIÓN</small></span></a><nav><?=nav_link('/admin/','Resumen')?><?=nav_link('/admin/?view=products','Productos')?><?=nav_link('/admin/editor.php','Edición Visual')?><?=nav_link('/admin/sections.php?module=presentation','Participación',$module==='presentation'?'active':'')?><?=nav_link('/admin/sections.php?module=impact','Impacto',$module==='impact'?'active':'')?><?=nav_link('/admin/sections.php?module=contacts','Contactos',$module==='contacts'?'active':'')?><?=nav_link('/admin/configuration.php','Configuración Web')?><?=nav_link('/admin/?view=media','Imágenes')?></nav><div class="admin-user"><strong><?=e($user['name'])?></strong><small><?=e($user['role'])?></small><a href="/admin/?view=logout">Cerrar sesión</a></div></aside><main class="admin-main"><header class="admin-top"><div><p class="admin-eyebrow">Contenido público</p><h1><?=e($labels[$module])?></h1></div><a class="site-button" href="<?=e($publicPath)?>" target="_blank" rel="noreferrer">Ver página ↗</a></header><?php if($flash):?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
