r="https://, mailto: o tel:"></label><label>Orden<input type="number" name="sort_order" value="<?=e($record['sort_order'])?>" min="0"></label><label class="check"><input type="checkbox" name="is_active" <?=$record['is_active']?'checked':''?>> Mostrar en la web</label><div class="form-actions"><a href="?module=contacts">Limpiar</a><button class="primary-button">Guardar canal</button></div></form></div>
<?php else: $record=$editing?:['id'=>0,'entry_type'=>'event','title_es'=>'','title_en'=>'','description_es'=>'','description_en'=>'','event_date'=>'','location_es'=>'','location_en'=>'','logo_path'=>'','cover_path'=>'','is_active'=>1,'sort_order'=>0];?><div class="module-tabs"><a href="#published-content">Publicado ahora <strong><?=count($entries)?></strong></a><a href="#content-editor"><?=$record['id']?'Editando':'Crear nuevo'?></a></div><div class="content-summary"><article><strong><?=$publishedCount?></strong><span>Visibles en la web</span></article><article><strong><?=count($entries)-$publishedCount?></strong><span>Ocultos</span></article><article><strong><?=array_sum(array_map(static fn(array $item):int=>(int)($item['media_count']??0),$entries))?></strong><span>Fotos en álbumes</span></article></div><div class="admin-split collection-manager"><section class="admin-panel" id="published-content"><div class="panel-heading"><div><p class="admin-eyebrow">Publicado ahora</p><h2><?=e($labels[$module])?> en la web</h2><p>Edita aquí los contenidos que ya aparecen en la página pública.</p></div><a class="secondary-button" href="?module=<?=e($module)?>#content-editor">+ Nuevo</a></div><div class="content-card-list"><?php if(!$entries):?><div class="content-empty"><strong>No hay contenido cargado</strong><p>Crea el primer registro para reemplazar el contenido de respaldo de la web.</p></div><?php endif;?><?php foreach($entries as $item):?><article data-entry-type="<?=e($item['entry_type'])?>" class="<?=$editingId===(int)$item['id']?'is-editing':''?>"><div class="content-card-media"><?php if($item['cover_path']):?><img src="<?=e($item['cover_path'])?>" alt=""><?php else:?><span><?=strtoupper(substr($item['entry_type'],0,1))?></span><?php endif;?></div><div class="content-card-copy"><div class="content-card-badges"><span class="status <?=$item['is_active']?'published':'draft'?>"><?=$item['is_active']?'Publicado':'Oculto'?></span><span class="entry-type"><?=$item['entry_type'